	// Construye el código de estado para consultar la tabla óptima.
	// Convierte casillas[] al formato del solver (1 = quien empieza la partida).
	function codigo_estado_tabla_optima()
	{
		var simbolo_primer_jugador = (quien_empieza_las_equis_o_los_circulos == "equis") ? "x" : "o";
		var codigo = "";
		for (var i = 0; i < 9; i++)
		{
			if (casillas[i] == "v") codigo += "0";
			else if (casillas[i] == simbolo_primer_jugador) codigo += "1";
			else codigo += "2";
		}
		// Cuando esta función se llama, le toca a la máquina.
		var turno_maquina = (quien_empieza_humano_o_maquina == "maquina") ? 1 : 2;
		return codigo + turno_maquina;
	}

	// Devuelve la casilla óptima para colocar (fase 1) consultando la tabla.
	// Si la tabla no contiene el estado (no debería ocurrir), recurre a la
	// función heurística original como medida de seguridad.
	function jugada_optima_tabla_fase1()
	{
		var entrada = tabla_optima_movibles[codigo_estado_tabla_optima()];
		if (entrada)
		{
			var j = parseInt(entrada.substring(1));
			if (j >= 0 && j <= 8) return j;
		}
		return posicion_inteligente_fichas_fijas();
	}

	// Devuelve [origen, destino] óptimo para mover (fase 2) consultando la tabla.
	// Si la tabla no contiene el estado, recurre a la función heurística original.
	function jugada_optima_tabla_fase2()
	{
		var entrada = tabla_optima_movibles[codigo_estado_tabla_optima()];
		if (entrada)
		{
			var j = parseInt(entrada.substring(1));
			if (j >= 9)
			{
				var resto = j - 9;
				return [Math.floor(resto / 9), resto % 9];
			}
		}
		return posicion_inteligente_fichas_movibles();
	}

