	// Construye el código de estado para consultar la tabla de fichas fijas.
	function codigo_estado_tabla_fijas()
	{
		var simbolo_primer_jugador = (quien_empieza_las_equis_o_los_circulos == "equis") ? "x" : "o";
		var codigo = "";
		for (var i = 0; i < 9; i++)
		{
			if (casillas[i] == "v") codigo += "0";
			else if (casillas[i] == simbolo_primer_jugador) codigo += "1";
			else codigo += "2";
		}
		var turno_maquina = (quien_empieza_humano_o_maquina == "maquina") ? 1 : 2;
		return codigo + turno_maquina;
	}

	// Devuelve la casilla óptima para fichas fijas consultando la tabla.
	// Si el estado no está en la tabla (no debería ocurrir en partida normal),
	// devuelve -1 para que el llamador use el fallback heurístico.
	function jugada_optima_tabla_fijas()
	{
		var entrada = tabla_optima_fijas[codigo_estado_tabla_fijas()];
		if (entrada) return parseInt(entrada.substring(1));
		return -1;
	}


