	// ========================================================================
	// MODAL DE AVISOS - sustituye a las llamadas mostrar_modal_aviso() del juego
	// ========================================================================
	function mostrar_modal_aviso(mensaje, titulo)
	{
		var overlay = document.getElementById('tr_modal_overlay');
		var tit = document.getElementById('tr_modal_title');
		var msg = document.getElementById('tr_modal_message');
		var btn = document.getElementById('tr_modal_btn');
		if (!overlay || !tit || !msg) { window.alert(mensaje); return; }
		tit.textContent = titulo || 'Aviso';
		msg.textContent = mensaje;
		overlay.classList.add('tr_show');
		setTimeout(function() { if (btn) btn.focus(); }, 50);
	}

	function cerrar_modal_aviso()
	{
		var overlay = document.getElementById('tr_modal_overlay');
		if (overlay) overlay.classList.remove('tr_show');
	}

	// Listeners globales del modal: Escape, Enter y click fuera lo cierran.
	document.addEventListener('keydown', function(ev) {
		var overlay = document.getElementById('tr_modal_overlay');
		if (overlay && overlay.classList.contains('tr_show'))
		{
			if (ev.key === 'Escape' || ev.key === 'Enter') cerrar_modal_aviso();
		}
	});
	document.addEventListener('click', function(ev) {
		var overlay = document.getElementById('tr_modal_overlay');
		if (overlay && ev.target === overlay) cerrar_modal_aviso();
	});

	// Exponer las funciones al scope global para que el atributo onclick
	// del botón del modal pueda invocarlas (los atributos HTML buscan en window).
	window.mostrar_modal_aviso = mostrar_modal_aviso;
	window.cerrar_modal_aviso = cerrar_modal_aviso;



